questionvariables.text:
Srx: matrix([1,0],[0,-1]); Sry: matrix([-1,0],[0,1]); Sryx: matrix([0,1],[1,0]); Srmyx: matrix([0,-1],[-1,0]);
Sr90: matrix([0,-1],[1,0]); Sr180: matrix([-1,0],[0,-1]); Sr270: matrix([0,1],[-1,0]);
symkeys: ["rx","ry","ryx","rmyx","r90","r180","r270"];
symmats: [Srx,Sry,Sryx,Srmyx,Sr90,Sr180,Sr270];
sm(k) := symmats[sublist_indices(symkeys, lambda([u], u=k))[1]];
sn(k) := sublist_indices(symkeys, lambda([u], u=k))[1];
skey(A) := block([j], j: sublist_indices(symmats, lambda([u], is(u=A))), if j=[] then "none" else symkeys[j[1]]);
/* Design: construct-an-instance pattern with dropdowns (graded by property; several pairs work). Source: original. Per entry: two valid pairs, an order-error pair, a pair that fails the constraint, a generic pair; every route reachable. */
clist: [["ry","rot"],["rx","ref"],["rx","rot"],["ry","ref"],["rmyx","ref"],["rmyx","rot"],["r270","ref"],["ryx","rot"],["ryx","ref"],["r90","ref"]];
tplist: [[["r90","rmyx"],["r180","rx"],["r90","ryx"],["rx","r180"],["r90","rx"]],[["ry","r180"],["ryx","r270"],["ryx","r90"],["r90","ryx"],["rx","rx"]],[["r90","ryx"],["r180","ry"],["r90","rmyx"],["ry","r180"],["r90","rx"]],[["rx","r180"],["ryx","r90"],["ryx","r270"],["r90","rmyx"],["rx","rx"]],[["rx","r270"],["ry","r90"],["rx","r90"],["r90","rx"],["rx","rx"]],[["r90","rx"],["r180","ryx"],["r90","ry"],["rx","r270"],["r90","ryx"]],[["rx","rmyx"],["ry","ryx"],["rx","ryx"],["r90","r180"],["rx","rx"]],[["r90","ry"],["r180","rmyx"],["r90","rx"],["rx","r90"],["r90","ryx"]],[["rx","r90"],["ry","r270"],["rx","r270"],["r90","ry"],["rx","rx"]],[["rx","ryx"],["ry","rmyx"],["rx","rmyx"],["r180","r270"],["rx","rx"]]];
ix: 1+rand(10);
t: clist[ix][1]; c: clist[ix][2]; Tm: sm(t); TP: tplist[ix];
firstok(u) := if c="rot" then member(u,["r90","r180","r270"]) else member(u,["rx","ry","ryx","rmyx"]);
v1a: TP[1][1]; v1b: TP[1][2]; v2a: TP[2][1]; v2b: TP[2][2]; oa: TP[3][1]; ob: TP[3][2];
ca: TP[4][1]; cb: TP[4][2]; ga: TP[5][1]; gb: TP[5][2];
/* the teacher's answer shown is the first valid pair; grading is by property */
opt1: [["rx", is(v1a="rx"), "reflection in the x-axis"], ["ry", is(v1a="ry"), "reflection in the y-axis"], ["ryx", is(v1a="ryx"), "reflection in the line y = x"], ["rmyx", is(v1a="rmyx"), "reflection in the line y = −x"], ["r90", is(v1a="r90"), "rotation of 90° anticlockwise about O"], ["r180", is(v1a="r180"), "rotation of 180° about O"], ["r270", is(v1a="r270"), "rotation of 90° clockwise about O"]];
opt2: [["rx", is(v1b="rx"), "reflection in the x-axis"], ["ry", is(v1b="ry"), "reflection in the y-axis"], ["ryx", is(v1b="ryx"), "reflection in the line y = x"], ["rmyx", is(v1b="rmyx"), "reflection in the line y = −x"], ["r90", is(v1b="r90"), "rotation of 90° anticlockwise about O"], ["r180", is(v1b="r180"), "rotation of 180° about O"], ["r270", is(v1b="r270"), "rotation of 90° clockwise about O"]];

feedbackvariables.text:
P1: sm(ans1); P2: sm(ans2);
g1: is(P2.P1 = Tm) and firstok(ans1);
g2: is(P1.P2 = Tm) and is(P2.P1 # Tm);
g3: is(P2.P1 = Tm);
alt1: if is(ans1 = v1a and ans2 = v1b) then v2a else v1a;
alt2: if is(ans1 = v1a and ans2 = v1b) then v2b else v1b;
